function celsiusToFahrenheit(celsius) {
  // Check if the input is a valid number
  if (typeof celsius !== 'number') {
    // If not a number, throw an error
    throw new Error('Input must be a number.');
  }

  // Apply the conversion formula: Celsius multiplied by 9/5
  const fahrenheit = celsius * (9 / 5) + 32;

  // Add 32 to complete the conversion
  // The formula is F = C * 9/5 + 32

  // Return the calculated Fahrenheit value
  return fahrenheit;
}

// Example usage:
// Converting 0 degrees Celsius
const freezingPointFahrenheit = celsiusToFahrenheit(0); // Expected: 32
// Converting 25 degrees Celsius
const roomTemperatureFahrenheit = celsiusToFahrenheit(25); // Expected: 77

