const countVowels = (str) => {
  let count = 0; // Initialize a counter for vowels
  const vowels = 'aeiou'; // Define a string containing all vowels

  // Convert the input string to lowercase to handle case-insensitivity
  const lowerStr = str.toLowerCase();

  // Iterate over each character of the lowercase string
  for (let i = 0; i < lowerStr.length; i++) {
    const char = lowerStr[i]; // Get the current character

    // Check if the current character is present in the vowels string
    if (vowels.includes(char)) {
      count++; // Increment the counter if it's a vowel
    }
  }

  return count; // Return the total count of vowels
};

