function generateFibonacci(n) {
  // Handle edge cases for n
  if (n <= 0) {
    return []; // Return empty array for non-positive n
  }
  if (n === 1) {
    return [0]; // The first Fibonacci number is 0
  }

  // Initialize the array with the first two Fibonacci numbers
  const fibSequence = [0, 1]; // Start with the base cases

  // Loop to generate the remaining Fibonacci numbers
  for (let i = 2; i < n; i++) {
    // Calculate the next number as the sum of the previous two
    const nextFib = fibSequence[i - 1] + fibSequence[i - 2]; // Fibonacci definition
    fibSequence.push(nextFib); // Add the new number to the sequence
  }

  return fibSequence; // Return the complete Fibonacci sequence
}

