const removeDuplicates = (arr) => {
  // Create an empty Set to store unique elements
  const uniqueElements = new Set();
  // Create an empty array to store the result
  const result = [];

  // Iterate over each element in the input array
  for (let i = 0; i < arr.length; i++) {
    const element = arr[i]; // Get the current element

    // Check if the element is not already in the Set
    if (!uniqueElements.has(element)) {
      uniqueElements.add(element); // Add the element to the Set
      result.push(element); // Add the element to the result array
    }
  }
  // The Set automatically handles uniqueness
  // This line converts the Set back into an array
  return result; // Return the new array with duplicates removed
};

