const calculateAverage = (arr) => {
  // Check if the array is empty to prevent division by zero
  if (arr.length === 0) {
    return 0; // Return 0 for an empty array, or throw an error depending on requirements
  }

  let sum = 0; // Initialize a variable to store the sum of array elements

  // Iterate over each number in the array
  for (let i = 0; i < arr.length; i++) {
    sum += arr[i]; // Add the current number to the sum
  }

  // Calculate the average by dividing the sum by the number of elements
  const average = sum / arr.length;

  // Return the calculated average
  return average;
};

