function isPrime(num) {
  // Prime numbers must be greater than 1
  if (num <= 1) {
    return false;
  }
  // 2 is the only even prime number
  if (num === 2) {
    return true;
  }
  // All other even numbers are not prime
  if (num % 2 === 0) {
    return false;
  }
  // Check for divisibility from 3 up to the square root of num
  // We can increment by 2 since we've already handled even numbers
  for (let i = 3; i * i <= num; i += 2) {
    // If num is divisible by i, it's not prime
    if (num % i === 0) {
      return false;
    }
  }
  // If no divisors were found, the number is prime
  return true; // Final return statement
}
// This function efficiently checks for primality
// It handles edge cases like 0, 1, and 2
// The loop optimization significantly reduces checks for larger numbers

