function fizzBuzz(n) {
  const result = []; // Initialize an empty array to store the results.

  for (let i = 1; i <= n; i++) { // Loop from 1 up to and including n.
    let output = ''; // Initialize an empty string for the current number's output.

    if (i % 3 === 0) { // Check if the number is a multiple of 3.
      output += 'Fizz'; // Append 'Fizz' if it is.
    }
    if (i % 5 === 0) { // Check if the number is a multiple of 5.
      output += 'Buzz'; // Append 'Buzz' if it is.
    }

    if (output === '') { // If no 'Fizz' or 'Buzz' was added,
      result.push(i); // push the number itself.
    } else {
      result.push(output); // Otherwise, push the generated string.
    }
  }

  return result; // Return the final array.
}

