const parseUrlParams = (url) => {
  const params = {}; // Initialize an empty object to store the parameters.
  const queryStringIndex = url.indexOf('?'); // Find the starting index of the query string.

  // If no query string is present, return the empty params object.
  if (queryStringIndex === -1) {
    return params;
  }

  // Extract the query string part of the URL.
  const queryString = url.substring(queryStringIndex + 1);

  // If the query string is empty, return the empty params object.
  if (queryString.length === 0) {
    return params;
  }

  // Split the query string into individual key-value pairs.
  const paramPairs = queryString.split('&');

  // Iterate over each key-value pair.
  paramPairs.forEach(pair => {
    const parts = pair.split('='); // Split each pair into key and value.
    if (parts.length === 2) {
      const key = decodeURIComponent(parts[0]); // Decode the key for special characters.
      const value = decodeURIComponent(parts[1]); // Decode the value.
      params[key] = value; // Assign the decoded key-value pair to the params object.
    }
  });

  return params; // Return the populated parameters object.
};

