function rollDice(sides) {
  // Check if sides is a positive integer
  if (sides <= 0 || !Number.isInteger(sides)) {
    // Throw an error for invalid input
    throw new Error("Number of sides must be a positive integer.");
  }

  // Generate a random number between 0 (inclusive) and 1 (exclusive)
  const randomNumber = Math.random();

  // Scale the random number to the desired range (0 to sides - 1)
  const scaledNumber = randomNumber * sides; // This will be between 0 and sides, non-inclusive for sides

  // Floor the scaled number to get an integer
  const flooredNumber = Math.floor(scaledNumber); // This will be between 0 and sides - 1

  // Add 1 to shift the range to 1 to sides (inclusive)
  const result = flooredNumber + 1; // This is the final random integer

  // Return the calculated random integer
  return result; // The dice roll result
}

