const calculateMedian = (arr) => {
  // Sort the array in ascending order.
  const sortedArr = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(sortedArr.length / 2); // Calculate the middle index.

  // Check if the array has an odd number of elements.
  if (sortedArr.length % 2 !== 0) {
    return sortedArr[mid]; // Return the middle element.
  } else {
    // Array has an even number of elements.
    const mid1 = sortedArr[mid - 1]; // Get the first of the two middle numbers.
    const mid2 = sortedArr[mid]; // Get the second of the two middle numbers.
    return (mid1 + mid2) / 2; // Return the average of the two middle numbers.
  }
};

