function playRockPaperScissors(playerChoice) {
  // Define possible choices for the game
  const choices = ['rock', 'paper', 'scissors'];
  // Generate a random index for the computer's choice
  const randomIndex = Math.floor(Math.random() * choices.length);
  // Get the computer's choice based on the random index
  const computerChoice = choices[randomIndex];

  // Handle a tie scenario
  if (playerChoice === computerChoice) {
    return 'Tie';
  }

  // Determine the outcome based on player's choice
  if (playerChoice === 'rock') {
    // If player chose rock, check against paper and scissors
    return (computerChoice === 'scissors') ? 'Win' : 'Loss'; // Rock beats scissors, loses to paper
  } else if (playerChoice === 'paper') {
    // If player chose paper, check against rock and scissors
    return (computerChoice === 'rock') ? 'Win' : 'Loss'; // Paper beats rock, loses to scissors
  } else if (playerChoice === 'scissors') {
    // If player chose scissors, check against rock and paper
    return (computerChoice === 'paper') ? 'Win' : 'Loss'; // Scissors beats paper, loses to rock
  }
  // This line should ideally not be reached with valid input
  return 'Invalid Choice'; // In case of an unexpected playerChoice
}

