function extractEmails(text) {
  // Regular expression to match email addresses
  // It looks for sequences of word characters, dots, or hyphens, followed by '@',
  // then more word characters, dots, or hyphens, then a dot, and finally 2-6 letters.
  const emailRegex = /[\w.-]+@[\w.-]+\.[A-Za-z]{2,6}/g;

  // Use match() to find all occurrences of the regex in the text
  const emails = text.match(emailRegex);

  // If no emails are found, match() returns null, so we return an empty array
  if (emails === null) {
    return [];
  }

  // Return the array of found email addresses
  return emails; // This line returns the result
}

