function truncateString(str, maxLength) {
  /* Check if the string's length is already within the limit */
  if (str.length <= maxLength) {
    return str; /* Return the original string if no truncation is needed */
  }

  /* Handle the edge case where maxLength is too small for "..." */
  if (maxLength <= 3) {
    /* If maxLength is 3 or less, return just dots to avoid negative slicing */
    return '.'.repeat(maxLength); /* Create a string of dots based on maxLength */
  }

  /* Calculate the length of the string before adding '...' */
  const truncatedLength = maxLength - 3;
  /* Slice the string to the calculated length */
  const truncatedStr = str.slice(0, truncatedLength);
  /* Append '...' to the truncated string */
  return truncatedStr + '...'; /* Concatenate the sliced part with ellipsis */
}

