const filterByProperty = (arr, prop, value) => {
  // Ensure the input array is actually an array
  if (!Array.isArray(arr)) {
    return []; // Return an empty array if input is not valid
  }

  // Use the filter method to iterate over the array
  const filteredArray = arr.filter(obj => {
    // Check if the object has the specified property
    if (obj && typeof obj === 'object' && obj.hasOwnProperty(prop)) {
      // Return true if the property's value matches the target value
      return obj[prop] === value;
    }
    // If the object doesn't have the property, or is not an object, exclude it
    return false;
  });

  // Return the newly filtered array
  return filteredArray; // This is the result of our filtering operation
};

