function formatCurrency(amount, currencySymbol) {
  // Ensure amount is a number and has two decimal places
  const fixedAmount = amount.toFixed(2); // Rounds to two decimal places

  // Split the number into integer and decimal parts
  let [integerPart, decimalPart] = fixedAmount.split('.'); 

  // Add commas for thousands separator to the integer part
  integerPart = integerPart.replace(/\B(?=(\d{3})+(?!\d))/g, ','); // Regex to insert commas

  // Construct the final formatted string
  const formattedString = `${currencySymbol}${integerPart}.${decimalPart}`; // Concatenate parts

  // Return the complete currency string
  return formattedString; // This is the output
}

