const getFileExtension = (filename) => {
  // Find the last occurrence of a dot in the filename
  const lastDotIndex = filename.lastIndexOf('.');

  // If no dot is found, there's no extension
  if (lastDotIndex === -1) {
    return ''; // Return an empty string as per requirements
  }

  // Extract the potential extension part
  const potentialExtension = filename.substring(lastDotIndex + 1);

  // Check if the potential extension contains a path separator
  // This handles cases like 'path/to/file.ext' correctly
  if (potentialExtension.includes('/') || potentialExtension.includes('\\')) {
    return ''; // No valid extension if a path separator is found after the last dot
  }

  // Return the extracted extension
  return potentialExtension; // This is the final step for a valid extension
};

