function isLeapYear(year) {
  // A year is a leap year if it is divisible by 4
  if (year % 4 === 0) {
    // But, if it's divisible by 100, it's not a leap year
    if (year % 100 === 0) {
      // Unless it's also divisible by 400
      if (year % 400 === 0) {
        return true; // Divisible by 400, so it is a leap year
      } else {
        return false; // Divisible by 100 but not by 400, so not a leap year
      }
    } else {
      return true; // Divisible by 4 but not by 100, so it is a leap year
    }
  } else {
    // Not divisible by 4, so definitely not a leap year
    return false;
  }
}
// Example usage:
// const year1 = 2000;
// const year2 = 1900;
// const year3 = 2024;
