function startsWith(str, prefix) {
  // Check if the prefix is longer than the string itself
  if (prefix.length > str.length) {
    return false; // A longer prefix cannot be at the start of a shorter string
  }

  // Iterate through the characters of the prefix
  for (let i = 0; i < prefix.length; i++) {
    // Compare characters at the same position in both strings
    if (str[i] !== prefix[i]) {
      return false; // If any character doesn't match, it's not a prefix
    }
  }

  // If the loop completes, all characters matched
  return true; // The string indeed starts with the given prefix
}

