const removeWhitespace = (str) => {
  // Ensure the input is actually a string.
  if (typeof str !== 'string') {
    // If not, convert it to a string for robust handling.
    str = String(str);
  }

  // Use a regular expression to match all whitespace characters globally.
  // The '\s' character class matches space, tab, new line, carriage return, form feed, vertical tab.
  // The 'g' flag ensures all occurrences are replaced, not just the first one.
  const cleanedString = str.replace(/\s/g, '');

  // Return the string after all whitespace has been removed.
  return cleanedString; // This is the final processed string.
