const formatPhoneNumber = (numbers) => {
  // Extract the first three digits for the area code
  const areaCode = numbers.slice(0, 3).join('');
  // Extract the next three digits for the prefix
  const prefix = numbers.slice(3, 6).join('');
  // Extract the last four digits for the line number
  const lineNumber = numbers.slice(6, 10).join('');

  // Start building the formatted string with the opening parenthesis
  let formattedNumber = `(${areaCode})`; // Area code enclosed in parentheses
  // Add a space after the area code
  formattedNumber += ' ';
  // Append the prefix
  formattedNumber += prefix;
  // Add a hyphen before the line number
  formattedNumber += '-';
  // Finally, append the line number
  formattedNumber += lineNumber;

  // Return the complete formatted phone number string
  return formattedNumber;
};

