const calculatePower = (base, exponent) => {
  // Handle the edge case where the exponent is 0
  if (exponent === 0) {
    return 1; // Any number raised to the power of 0 is 1
  }

  let result = 1; // Initialize the result to 1
  // Use a loop to multiply the base by itself 'exponent' times
  for (let i = 0; i < exponent; i++) {
    result *= base; // Multiply result by base in each iteration
  }
  // The loop has completed, and result now holds the calculated power
  return result; // Return the final calculated power
};

