const getUniqueValues = (arr) => {
  // Create a new Set to store unique values efficiently.
  const uniqueSet = new Set();
  // Initialize an empty array to hold the unique values in order.
  const result = [];

  // Iterate over each element in the input array.
  for (let i = 0; i < arr.length; i++) {
    const currentValue = arr[i]; // Get the current element.

    // Check if the current value is already present in the Set.
    if (!uniqueSet.has(currentValue)) {
      uniqueSet.add(currentValue); // Add the value to the Set if it's new.
      result.push(currentValue); // Add the value to the result array.
    }
    // If the value is already in the Set, we do nothing (it's not unique).
  }
  // Return the array containing only the unique values.
  return result;
};

