function findMissingNumber(nums) {
  const n = nums.length; // Determine the length of the input array.
  let expectedSum = 0; // Initialize a variable to store the sum of numbers from 0 to n.

  // Calculate the sum of numbers from 0 to n.
  for (let i = 0; i <= n; i++) {
    expectedSum += i; // Add each number to the expected sum.
  }

  let actualSum = 0; // Initialize a variable to store the sum of numbers present in the array.

  // Calculate the sum of numbers in the given array.
  for (let i = 0; i < n; i++) {
    actualSum += nums[i]; // Accumulate the sum of array elements.
  }

  // The missing number is the difference between the expected sum and the actual sum.
  return expectedSum - actualSum; // Return the result of the subtraction.
}

