  // Ensure principal and time are non-negative
  if (principal < 0 || time < 0) {
    // Interest cannot be calculated for negative principal or time
    throw new Error('Principal and time cannot be negative.');
  }

  // The formula for simple interest is P * R * T
  const interest = principal * rate * time;

