function formatDateToDMY(dateObj) {
  // Get the day of the month from the Date object.
  const day = dateObj.getDate();
  // Get the month (0-indexed) and add 1 for actual month number.
  const month = dateObj.getMonth() + 1;
  // Get the full year.
  const year = dateObj.getFullYear();

  // Pad single-digit day with a leading zero.
  const formattedDay = day < 10 ? '0' + day : day;
  // Pad single-digit month with a leading zero.
  const formattedMonth = month < 10 ? '0' + month : month;

  // Concatenate the formatted parts with '/' as a separator.
  return `${formattedDay}/${formattedMonth}/${year}`; // Return the final formatted string.
}

