const calculateRectanglePerimeter = (length, width) => {
  // Check if both inputs are valid numbers
  if (typeof length !== 'number' || typeof width !== 'number') {
    // Throw an error if inputs are not numbers
    throw new Error('Both length and width must be numbers.');
  }

  // Ensure dimensions are non-negative
  if (length < 0 || width < 0) {
    // Rectangles cannot have negative dimensions
    throw new Error('Length and width cannot be negative.');
  }

  // Calculate the perimeter using the standard formula
  const perimeter = 2 * (length + width); // Perimeter formula

  // Return the calculated perimeter
  return perimeter; // The final result
};

