function countLines(text) {
  // Check for empty string case
  if (text === '') {
    return 0;
  }

  // Split the string by newline character
  const lines = text.split('\n'); // This creates an array of lines.

  // The length of the array is the number of lines
  const numberOfLines = lines.length; // Store the result in a variable.

  // Handle the edge case where the string might end with a newline
  // If it does, split will produce an extra empty string at the end.
  // For example, "a\n" splits into ["a", ""]. We want to count this as 1 line.
  if (text.endsWith('\n') && numberOfLines > 1) { // Check if it ends with newline AND has more than one part.
    return numberOfLines - 1; // Subtract 1 if the last element is an empty string from a trailing newline.
  }

  // Return the calculated number of lines
  return numberOfLines; // This is the final result.
}

