const hexToRgb = (hexColor) => {
  // Remove the '#' if it's present at the beginning.
  const hex = hexColor.startsWith('#') ? hexColor.slice(1) : hexColor;

  // Parse the red component from the first two characters.
  const r = parseInt(hex.substring(0, 2), 16);

  // Parse the green component from the next two characters.
  const g = parseInt(hex.substring(2, 4), 16);

  // Parse the blue component from the last two characters.
  const b = parseInt(hex.substring(4, 6), 16);

  // Check for NaN values, indicating invalid hex input.
  if (isNaN(r) || isNaN(g) || isNaN(b)) {
    throw new Error('Invalid hexadecimal color code format.'); // Handle invalid input gracefully.
  }

  // Return the RGB components as an array.
  return [r, g, b]; // This is the final RGB array.
};

