const longestCommonPrefix = (strs) => {
  if (strs.length === 0) { // Handle empty input array
    return "";
  }

  // Assume the first string is the initial prefix
  let prefix = strs[0];

  for (let i = 1; i < strs.length; i++) { // Iterate through the rest of the strings
    const currentStr = strs[i];
    let j = 0; // Initialize character index for comparison

    // Compare characters of prefix and current string
    while (j < prefix.length && j < currentStr.length && prefix[j] === currentStr[j]) {
      j++; // Increment index if characters match
    }

    // Update the prefix to the common part found
    prefix = prefix.substring(0, j); // Shorten the prefix if mismatch occurs

    if (prefix === "") { // If prefix becomes empty, no common prefix exists
      return "";
    }
  }

  return prefix; // Return the final longest common prefix
};

