        digit = digit - 9; // Sum its digits (e.g., 12 becomes 1+2=3, which is 12-9)
      }
    }
    sum += digit; // Add the (possibly modified) digit to the total sum
    isSecondDigit = !isSecondDigit; // Toggle the flag for the next digit
  }

  // A card is valid if the total sum modulo 10 is 0
  return sum % 10 === 0;
};

