function generateAcronym(phrase) {
  // Split the phrase into words
  const words = phrase.split(/[\s-]+/); // Handles spaces and hyphens as delimiters

  let acronym = ''; // Initialize an empty string to build the acronym

  // Iterate through each word
  for (const word of words) {
    // Check if the word is not empty after potential splitting
    if (word.length > 0) {
      // Find the first alphabetic character
      const firstAlphaChar = word.match(/[a-zA-Z]/); // Regular expression to find any letter

      // If an alphabetic character is found
      if (firstAlphaChar) {
        // Append its uppercase version to the acronym
        acronym += firstAlphaChar[0].toUpperCase();
      }
    }
  }

  return acronym; // Return the generated acronym
}

