const hammingWeight = (n) => {
  let count = 0; // Initialize a counter for '1' bits.

  // Loop continues as long as n is not zero.
  while (n !== 0) {
    // Check if the least significant bit is a '1'.
    if ((n & 1) === 1) {
      count++; // Increment count if the bit is '1'.
    }
    // Right shift n by 1 bit, effectively checking the next bit.
    n >>>= 1; // Unsigned right shift to handle large positive numbers correctly.
  }
  return count; // Return the total count of '1' bits.
};

// Example usage:
// console.log(hammingWeight(1)); // Expected output: 1
// console.log(hammingWeight(7)); // Expected output: 3
