const caesarCipher = (text, shift) => {
  let result = ''; // Initialize an empty string to store the encrypted result.
  for (let i = 0; i < text.length; i++) { // Loop through each character in the input text.
    let char = text[i];
    if (char >= 'a' && char <= 'z') { // Check if the character is a lowercase letter.
      let code = char.charCodeAt(0); // Get the ASCII code of the character.
      code = ((code - 97 + shift) % 26) + 97; // Apply the shift and wrap around using modulo 26 for 'a'-'z'.
      result += String.fromCharCode(code); // Convert the new ASCII code back to a character.
    } else if (char >= 'A' && char <= 'Z') { // Check if the character is an uppercase letter.
      let code = char.charCodeAt(0);
      code = ((code - 65 + shift) % 26) + 65; // Apply the shift and wrap around for 'A'-'Z'.
      result += String.fromCharCode(code); // Append the shifted character to the result.
    } else {
      result += char; // Non-alphabetic characters are appended unchanged.
    }
  }
  return result; // Return the final encrypted string.
};

