function largeFactorial(n) {
  // Initialize 'res' array with '1' as the starting point for factorial calculation.
  let res = [1];
  let resSize = 1; // Current size of the result array.

  // Iterate from 2 up to n to multiply each number.
  for (let x = 2; x <= n; x++) {
    let carry = 0; // Initialize carry for multiplication.

    // Traverse the 'res' array from right to left.
    for (let i = 0; i < resSize; i++) {
      let prod = res[i] * x + carry; // Multiply digit by x and add carry.
      res[i] = prod % 10; // Store the last digit of prod.
      carry = Math.floor(prod / 10); // Update carry for the next iteration.
    }

    // Process remaining carry.
    while (carry > 0) {
      res[resSize] = carry % 10; // Add new digits to the end of the array.
      carry = Math.floor(carry / 10); // Reduce carry.
      resSize++; // Increment the size of the result.
    }
  }

  // Reverse the array and join elements to form the final string.
  return res.reverse().join(''); // The result is built in reverse order, so we reverse it.
}

