const firstUniqChar = (s) => {
  const charCounts = new Map(); // Create a map to store character counts.

  // First pass: populate the map with character frequencies.
  for (let i = 0; i < s.length; i++) {
    const char = s[i]; // Get the current character.
    charCounts.set(char, (charCounts.get(char) || 0) + 1); // Increment its count.
  }

  // Second pass: find the first character with a count of 1.
  for (let i = 0; i < s.length; i++) {
    const char = s[i]; // Get the character at the current index.
    if (charCounts.get(char) === 1) { // Check if its count is 1.
      return i; // If it is, return its index.
    }
  }

  return -1; // If no unique character is found, return -1.
};

