const isValidParentheses = (s) => {
    const stack = []; // Initialize an empty stack to store opening brackets
    const map = {      // Create a map to store corresponding closing brackets
        "(": ")",
        "{": "}",
        "[": "]",
    };

    for (let i = 0; i < s.length; i++) { // Iterate through each character in the input string
        const char = s[i];

        if (map[char]) { // If the character is an opening bracket
            stack.push(char); // Push it onto the stack
        } else { // If the character is a closing bracket
            if (stack.length === 0) { // If stack is empty, no matching opening bracket
                return false;
            }
            const lastOpen = stack.pop(); // Pop the last opened bracket
            if (map[lastOpen] !== char) { // Check if the popped bracket's closure matches the current char
                return false; // Mismatch found, string is invalid
            }
        }
    }

    return stack.length === 0; // The string is valid only if the stack is empty at the end
};

