function flattenArray(arr) {
  let result = []; // Initialize an empty array to store the flattened elements.

  // Iterate over each element in the input array.
  for (let i = 0; i < arr.length; i++) {
    const currentElement = arr[i]; // Get the current element.

    // Check if the current element is an array.
    if (Array.isArray(currentElement)) {
      // If it's an array, recursively call flattenArray on it
      // and concatenate the result to our main result array.
      result = result.concat(flattenArray(currentElement));
    } else {
      // If it's not an array, it's a primitive value.
      // Push the primitive value directly to the result array.
      result.push(currentElement); // Add the non-array element.
    }
  }
  return result; // Return the final flattened array.
}

