const arrayIntersection = (nums1, nums2) => {
  // Create a Set from the first array to efficiently check for existence
  const set1 = new Set(nums1);
  // Initialize an empty array to store the intersection elements
  const intersection = [];

  // Iterate over the second array
  for (const num of nums2) {
    // Check if the current number from nums2 exists in set1
    if (set1.has(num)) {
      // If it exists, add it to the intersection array
      intersection.push(num);
      // Remove the number from set1 to ensure uniqueness in the result
      set1.delete(num);
    }
  }
  // The result is the array of unique common elements
  return intersection;
};

