function decimalToBinary(decimalNum) {
  if (decimalNum === 0) { // Handle the edge case for zero input
    return '0';
  }

  let binaryString = ''; // Initialize an empty string to build the binary representation
  let tempNum = decimalNum; // Use a temporary variable to avoid modifying the original input

  while (tempNum > 0) { // Loop as long as there's a number to process
    binaryString = (tempNum % 2) + binaryString; // Get the remainder (0 or 1) and prepend it
    tempNum = Math.floor(tempNum / 2); // Divide by 2 and take the floor for the next iteration
  }

  return binaryString; // Return the final binary string
}

