class Queue {
  constructor() {
    this.elements = []; // Initialize an empty array to store queue elements
  }

  enqueue(element) {
    this.elements.push(element); // Add the element to the end of the array
  }

  dequeue() {
    if (this.isEmpty()) { // Check if the queue is empty
      return null; // Return null if there are no elements to dequeue
    }
    return this.elements.shift(); // Remove and return the first element of the array
  }

  isEmpty() {
    return this.elements.length === 0; // Check if the array has no elements
  }

  size() {
    return this.elements.length; // Return the current number of elements in the queue
  }
}

