const simpleMovingAverage = (data, windowSize) => {
  // Initialize an empty array to store the calculated averages.
  const averages = [];

  // Iterate through the data array, considering each possible window.
  for (let i = 0; i <= data.length - windowSize; i++) {
    // Extract the current window from the data array.
    const window = data.slice(i, i + windowSize);

    // Calculate the sum of numbers within the current window.
    const sum = window.reduce((acc, val) => acc + val, 0);

    // Calculate the average for the current window.
    const average = sum / windowSize;

    // Add the calculated average to the results array.
    averages.push(average); // Pushes the average into the results.
  }

  // Return the array containing all calculated simple moving averages.
  return averages; // The final output array.
};

