const majorityElement = (nums) => {
  let candidate = 0; // Initialize a candidate for the majority element.
  let count = 0;     // Initialize a counter for the current candidate.

  // Iterate through each number in the input array.
  for (const num of nums) {
    if (count === 0) {
      candidate = num; // If count is 0, set the current number as a new candidate.
    }
    // If the current number is the candidate, increment the count.
    if (num === candidate) {
      count++;
    } else {
      // If not, decrement the count.
      count--;
    }
  }

  // The candidate variable now holds the majority element.
  // This algorithm (Boyer-Moore Voting Algorithm) guarantees that
  // the final candidate will be the majority element if one exists.
  return candidate; // Return the identified majority element.
};

