function stringPermutations(str) {
  // Initialize an empty array to store the unique permutations.
  const result = [];

  // Helper function to generate permutations recursively.
  function permute(currentPermutation, remainingChars) {
    // Base case: if no characters are remaining, add the current permutation to the result.
    if (remainingChars.length === 0) {
      result.push(currentPermutation);
      return;
    }

    // Iterate through the remaining characters.
    for (let i = 0; i < remainingChars.length; i++) {
      const char = remainingChars[i]; // Get the current character.

      // Skip duplicate characters to avoid redundant permutations.
      if (i > 0 && remainingChars[i] === remainingChars[i - 1]) {
        continue;
      }

      // Recursively call permute with the updated permutation and remaining characters.
      permute(
        currentPermutation + char,
        remainingChars.slice(0, i) + remainingChars.slice(i + 1)
      );
    }
  }

  // Sort the input string to handle duplicates effectively during the permutation process.
  const sortedStr = str.split('').sort().join('');

  // Start the permutation generation.
  permute('', sortedStr);

  // Return the array of unique permutations.
  return result;
}

