const isPowerOfTwo = (n) => {
  // Edge case: numbers less than or equal to 0 are not powers of two.
  if (n <= 0) {
    return false;
  }

  // A power of two in binary has exactly one '1' bit.
  // For example: 1 (0001), 2 (0010), 4 (0100), 8 (1000).

  // A common trick to check for a single '1' bit is (n & (n - 1)).
  // If n is a power of two, then n-1 will have all bits to the right of the
  // single '1' bit set to '1', and the '1' bit itself will be '0'.
  // Example: n = 8 (1000), n - 1 = 7 (0111).
  // n & (n - 1) = 1000 & 0111 = 0000.
  // This operation effectively clears the least significant '1' bit.

  // If n is a power of two, n & (n - 1) will be 0.
  return (n & (n - 1)) === 0; // Perform the bitwise AND operation.
};

// Example usage:
// console.log(isPowerOfTwo(1)); // true
// console.log(isPowerOfTwo(2)); // true
// console.log(isPowerOfTwo(3)); // false
// console.log(isPowerOfTwo(4)); // true
// console.log(isPowerOfTwo(0)); // false
// console.log(isPowerOfTwo(-1)); // false

