const deepMerge = (obj1, obj2) => {
  const newObj = { ...obj1 }; // Create a shallow copy of the first object

  for (const key in obj2) { // Iterate over keys in the second object
    if (Object.prototype.hasOwnProperty.call(obj2, key)) { // Ensure it's an own property
      if (typeof newObj[key] === 'object' && newObj[key] !== null &&
          typeof obj2[key] === 'object' && obj2[key] !== null &&
          !Array.isArray(newObj[key]) && !Array.isArray(obj2[key])) { // Check if both are non-null, non-array objects
        newObj[key] = deepMerge(newObj[key], obj2[key]); // Recursively merge nested objects
      } else {
        newObj[key] = obj2[key]; // Value from the second object takes precedence
      }
    }
  }
  return newObj; // Return the newly merged object
};

