const hammingDistance = (x, y) => {
  let xorResult = x ^ y; // XOR operation to find differing bits
  let distance = 0;      // Initialize Hamming distance counter

  // Loop while xorResult is not zero
  while (xorResult !== 0) {
    // Check if the least significant bit is 1
    if ((xorResult & 1) === 1) {
      distance++; // Increment distance if the bit is set
    }
    xorResult >>= 1; // Right shift to check the next bit
  }

  return distance; // Return the calculated Hamming distance
};

// Example usage:
// console.log(hammingDistance(1, 4)); // Expected output: 2
// console.log(hammingDistance(3, 1)); // Expected output: 1

