const findAllDivisors = (n) => {
  const divisors = []; // Initialize an empty array to store divisors.

  // Iterate from 1 up to the square root of n.
  for (let i = 1; i * i <= n; i++) {
    if (n % i === 0) { // Check if 'i' is a divisor of 'n'.
      divisors.push(i); // Add 'i' to the divisors array.
      if (i * i !== n) { // If 'i' is not the square root of 'n',
        divisors.push(n / i); // then n/i is also a divisor and different from 'i'.
      }
    }
  }

  // Sort the divisors in ascending order.
  divisors.sort((a, b) => a - b); // Use a comparison function for numerical sorting.

  return divisors; // Return the array of all divisors.
};

// Example usage:
// console.log(findAllDivisors(10)); // Expected: [1, 2, 5, 10]
// console.log(findAllDivisors(7));  // Expected: [1, 7]
// console.log(findAllDivisors(36)); // Expected: [1, 2, 3, 4, 6, 9, 12, 18, 36]

