const extractUniqueWords = (text) => {
  // Use a regular expression to match words, ignoring punctuation.
  // \b matches word boundaries, [a-zA-Z]+ matches one or more letters.
  const words = text.match(/\b[a-zA-Z]+\b/g);

  // Handle cases where no words are found.
  if (!words) {
    return [];
  }

  // Create a Set to store unique words. Sets automatically handle uniqueness.
  const uniqueWordsSet = new Set();

  // Iterate over each word extracted.
  for (const word of words) {
    // Convert the word to lowercase before adding it to the Set.
    const lowercasedWord = word.toLowerCase();
    // Add the lowercased word to the Set.
    uniqueWordsSet.add(lowercasedWord); // This ensures uniqueness and case-insensitivity.
  }

  // Convert the Set back into an array.
  return Array.from(uniqueWordsSet); // The final result is an array of unique, lowercase words.
};

