const hasEventCollisions = (events) => {
  // Sort events by their start time to simplify collision checking
  events.sort((a, b) => a.start - b.start);

  // Iterate through the sorted events
  for (let i = 0; i < events.length - 1; i++) {
    const currentEvent = events[i]; // Get the current event
    const nextEvent = events[i + 1]; // Get the next event in the sorted list

    // Check for overlap condition
    // An overlap occurs if the current event's end time is after the next event's start time
    if (currentEvent.end > nextEvent.start) {
      // This covers cases like [9, 10] and [9.5, 11] where 10 > 9.5
      // Or [9, 11] and [10, 12] where 11 > 10
      return true; // Collision detected
    }
    // No collision between currentEvent and nextEvent
  }
  // If the loop completes, no overlaps were found among any adjacent events
  return false; // No collisions
};

