function calculateStandardDeviation(numbers) {
  if (numbers.length < 2) {
    // Standard deviation is undefined or 0 for fewer than 2 elements.
    return 0;
  }

  // Calculate the sum of all numbers.
  const sum = numbers.reduce((acc, num) => acc + num, 0);
  // Calculate the mean (average) of the numbers.
  const mean = sum / numbers.length;

  // Calculate the sum of squared differences from the mean.
  const sumOfSquaredDifferences = numbers.reduce((acc, num) => {
    const diff = num - mean; // Calculate the difference from the mean.
    return acc + diff * diff; // Add the squared difference.
  }, 0);

  // Calculate the variance for a sample.
  const variance = sumOfSquaredDifferences / (numbers.length - 1);

  // The standard deviation is the square root of the variance.
  return Math.sqrt(variance); // Return the final standard deviation.
}

