const replaceAllOccurrences = (text, find, replace) => {
  // Check if the 'find' string is empty to avoid infinite loops
  if (find.length === 0) {
    return text; // Return the original text if 'find' is empty
  }

  let result = ''; // Initialize an empty string to store the modified text
  let currentIndex = 0; // Keep track of the current position in the original text

  // Loop through the text until no more occurrences of 'find' are found
  while (true) {
    // Find the index of the next occurrence of 'find' starting from currentIndex
    const foundIndex = text.indexOf(find, currentIndex);

    // If 'find' is not found, append the rest of the text and break the loop
    if (foundIndex === -1) {
      result += text.substring(currentIndex); // Append the remaining part of the string
      break; // Exit the loop as no more occurrences are found
    }

    // Append the part of the text before the found occurrence
    result += text.substring(currentIndex, foundIndex);
    // Append the replacement string
    result += replace;
    // Update currentIndex to continue searching after the replaced substring
    currentIndex = foundIndex + find.length;
  }

  return result; // Return the final string with all replacements
};

