const rotateArray = (nums, k) => {
  const n = nums.length; // Get the length of the input array.
  k %= n; // Ensure k is within the bounds of the array length.

  // If k is 0 or the array is empty, no rotation is needed.
  if (k === 0 || n === 0) {
    return nums;
  }

  // Create a new array to store the rotated elements.
  const rotated = new Array(n);

  // Populate the first part of the rotated array with elements from the end of the original array.
  for (let i = 0; i < k; i++) {
    rotated[i] = nums[n - k + i]; // Place elements from the end to the beginning.
  }

  // Populate the second part of the rotated array with the remaining elements from the beginning of the original array.
  for (let i = k; i < n; i++) {
    rotated[i] = nums[i - k]; // Shift remaining elements to their new positions.
  }

  // Copy the elements from the temporary rotated array back to the original nums array.
  for (let i = 0; i < n; i++) {
    nums[i] = rotated[i]; // Overwrite the original array with the rotated values.
  }

  return nums; // Return the modified array.
};

