const isDigitsOnly = (str) => {
  // Check if the input is actually a string
  if (typeof str !== 'string') {
    return false; // Return false if not a string
  }

  // Iterate over each character in the string
  for (let i = 0; i < str.length; i++) {
    const char = str[i]; // Get the current character

    // Check if the character is a digit using charCodeAt
    // ASCII values for '0' through '9' are 48 through 57
    if (char.charCodeAt(0) < 48 || char.charCodeAt(0) > 57) {
      return false; // If any character is not a digit, return false
    }
  }

  // If the loop completes, all characters were digits
  // Also handle empty string case: an empty string contains no non-digits, so it passes
  return true; // All characters are digits
};

