const binaryToDecimal = (binaryStr) => {
  let decimal = 0; // Initialize the decimal accumulator
  const len = binaryStr.length; // Get the length of the binary string

  // Iterate over the binary string from right to left (least significant bit to most significant bit)
  for (let i = 0; i < len; i++) {
    const bit = parseInt(binaryStr[len - 1 - i]); // Get the current bit and convert it to an integer

    // Check if the bit is valid (0 or 1)
    if (isNaN(bit) || (bit !== 0 && bit !== 1)) {
      throw new Error("Invalid binary string: Contains non-binary characters."); // Handle invalid input
    }

    // Multiply the bit by the appropriate power of 2 and add to the decimal total
    decimal += bit * Math.pow(2, i); // Calculate 2 to the power of i
  }

  return decimal; // Return the final decimal value
};

