function getNestedProperty(obj, path) {
  // Split the path string into an array of keys
  const keys = path.split('.');
  let current = obj; // Initialize current with the given object

  // Iterate over each key in the path
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i]; // Get the current key

    // Check if current is null or undefined, or if the key does not exist on current
    if (current === null || typeof current === 'undefined' || !current.hasOwnProperty(key)) {
      return undefined; // If any part of the path is missing, return undefined
    }
    current = current[key]; // Move deeper into the object
  }
  // After iterating through all keys, current holds the final value
  return current; // Return the retrieved value
}

