function range(start, end, step = 1) {
  const result = []; // Initialize an empty array to store the range
  if (step === 0) { // Handle the edge case of a zero step to prevent infinite loops
    throw new Error("Step cannot be zero.");
  }

  if (start < end) { // Check if the range is increasing
    for (let i = start; i <= end; i += step) { // Loop from start to end, incrementing by step
      result.push(i); // Add the current number to the result array
    }
  } else if (start > end) { // Check if the range is decreasing
    if (step > 0) { // If decreasing, step must be negative
        step = -step; // Convert positive step to negative for decreasing range
    }
    for (let i = start; i >= end; i += step) { // Loop from start to end, decrementing by step
      result.push(i); // Add the current number to the result array
    }
  } else { // Case where start and end are equal
    result.push(start); // If start and end are the same, include only that number
  }
  return result; // Return the generated array of numbers
}

