const isPalindromeCI = (str) => {
  // Convert the string to lowercase to ignore case
  const lowerStr = str.toLowerCase();

  // Remove non-alphanumeric characters using a regular expression
  const cleanedStr = lowerStr.replace(/[^a-z0-9]/g, '');

  // Initialize pointers for the start and end of the cleaned string
  let left = 0;
  let right = cleanedStr.length - 1; // Set right pointer to the last character

  // Loop while the left pointer is less than the right pointer
  while (left < right) {
    // Compare characters at the left and right pointers
    if (cleanedStr[left] !== cleanedStr[right]) {
      return false; // If characters don't match, it's not a palindrome
    }
    left++; // Move the left pointer one step to the right
    right--; // Move the right pointer one step to the left
  }

  // If the loop completes, all characters matched, so it's a palindrome
  return true;
};

