const wordFrequency = (text) => {
  // Create an empty object to store word frequencies.
  const frequencies = {};

  // Convert the text to lowercase and remove punctuation.
  // The regex /[^\w\s]/g matches any character that is NOT a word character or whitespace.
  const cleanedText = text.toLowerCase().replace(/[^\w\s]/g, '');

  // Split the cleaned text into an array of words.
  const words = cleanedText.split(/\s+/);

  // Iterate over each word in the array.
  for (const word of words) {
    // Check if the word is not empty (to handle multiple spaces).
    if (word) {
      // Increment the frequency of the word.
      // If the word is not yet a key in frequencies, initialize it to 0 before incrementing.
      frequencies[word] = (frequencies[word] || 0) + 1;
    }
  }

  // Return the object containing word frequencies.
  return frequencies;
};

