const longestPalindromeSubstring = (s) => {
  if (s.length < 1) return ""; // Handle empty or single-character strings

  let start = 0; // Initialize starting index of the longest palindrome
  let maxLength = 1; // Initialize max length of the longest palindrome

  // Helper function to expand around a center
  const expandAroundCenter = (left, right) => {
    while (left >= 0 && right < s.length && s[left] === s[right]) { // Check bounds and character equality
      left--; // Move left pointer inwards
      right++; // Move right pointer outwards
    }
    return right - left - 1; // Return the length of the palindrome found
  };

  for (let i = 0; i < s.length; i++) { // Iterate through each character as a potential center
    let len1 = expandAroundCenter(i, i); // Check for odd-length palindromes (e.g., "aba")
    let len2 = expandAroundCenter(i, i + 1); // Check for even-length palindromes (e.g., "abba")

    let len = Math.max(len1, len2); // Get the maximum length from both cases

    if (len > maxLength) { // If a new longest palindrome is found
      maxLength = len; // Update the maximum length
      // Calculate the new starting index for the longest palindrome
      start = i - Math.floor((len - 1) / 2); 
    }
  }

  return s.substring(start, start + maxLength); // Return the longest palindromic substring
};

