class Stack {
  constructor() {
    this.elements = []; // Initialize an empty array to store stack elements
  }

  push(element) {
    this.elements.push(element); // Add the new element to the end of the array
  }

  pop() {
    if (this.isEmpty()) { // Check if the stack is empty
      return null; // Return null if there are no elements to pop
    }
    return this.elements.pop(); // Remove and return the last element from the array
  }

  isEmpty() {
    return this.elements.length === 0; // Check if the array length is zero
  }

  peek() {
    if (this.isEmpty()) { // Ensure the stack isn't empty before peeking
      return null;
    }
    return this.elements[this.elements.length - 1]; // Return the top element without removing it
  }

  size() {
    return this.elements.length; // Return the number of elements in the stack
  }
}

