function sumPrimesUpTo(n) {
  let sum = 0; // Initialize sum of primes

  // Helper function to check if a number is prime
  function isPrime(num) {
    if (num <= 1) return false; // Numbers less than or equal to 1 are not prime
    for (let i = 2; i * i <= num; i++) { // Optimized loop: check divisibility up to sqrt(num)
      if (num % i === 0) { // If divisible, it's not prime
        return false;
      }
    }
    return true; // If no divisors found, it's prime
  }

  // Iterate from 2 up to n (inclusive)
  for (let i = 2; i <= n; i++) { 
    if (isPrime(i)) { // Check if the current number is prime
      sum += i; // Add prime numbers to the sum
    }
  }
  return sum; // Return the total sum of primes
}

