const findSingleNumber = (nums) => {
  let single = 0; // Initialize a variable to store the single number.

  // Iterate through each number in the input array.
  for (let i = 0; i < nums.length; i++) {
    single ^= nums[i]; // Use the XOR bitwise operator.
  }
  // The XOR property: a ^ a = 0 and a ^ 0 = a.
  // This means if a number appears twice, its XOR with itself cancels out to 0.
  // The single number, which appears only once, will remain.

