  for (let i = 0; i < codeLength; i++) {
    // Generate a random index within the range of available characters
    const randomIndex = Math.floor(Math.random() * characters.length);
    // Append the character at the random index to the short code
    shortCode += characters.charAt(randomIndex);
  }

  // In a real application, we would store longUrl -> shortCode mapping here.
  // For this task, we just return the generated code.
  return shortCode; // Return the generated 6-character short code
}

