const transposeMatrix = (matrix) => {
  if (!matrix || matrix.length === 0 || matrix[0].length === 0) { // Handle empty or invalid input matrices
    return [];
  }

  const numRows = matrix.length; // Get the number of rows in the original matrix
  const numCols = matrix[0].length; // Get the number of columns in the original matrix

  // Create a new matrix for the transposed result, initialized with nulls or undefined
  const transposed = Array(numCols).fill(null).map(() => Array(numRows).fill(null));

  for (let i = 0; i < numRows; i++) { // Iterate over rows of the original matrix
    for (let j = 0; j < numCols; j++) { // Iterate over columns of the original matrix
      transposed[j][i] = matrix[i][j]; // Swap row and column indices for transposition
    }
  }

  return transposed; // Return the newly created transposed matrix
};

