    for (let j = 0; j < numCols; j++) { /* Iterate over columns of the original matrix */
      transposed[j][i] = matrix[i][j]; /* Swap row and column indices for transposition */
    }
  }

  return transposed; /* Return the newly created transposed matrix */
};

