const isIsogram = (str) => {
  // Convert the input string to lowercase to handle case insensitivity
  const lowerStr = str.toLowerCase();
  // Create a Set to store unique characters encountered
  const charSet = new Set();

  // Iterate over each character in the lowercase string
  for (let i = 0; i < lowerStr.length; i++) {
    const char = lowerStr[i]; // Get the current character

    // Check if the character is already in the Set
    if (charSet.has(char)) {
      // If it is, the string is not an isogram
      return false;
    }
    // Add the current character to the Set
    charSet.add(char); // This adds a unique character
  }

  // If the loop completes without returning false, the string is an isogram
  return true; // All characters were unique
};

