const maxSubArraySum = (nums) => {
  let maxCurrent = nums[0]; // Initialize maxCurrent with the first element
  let maxGlobal = nums[0];  // Initialize maxGlobal with the first element

  for (let i = 1; i < nums.length; i++) { // Iterate through the array starting from the second element
    const num = nums[i]; // Get the current number

    // Kadane's algorithm: decide whether to extend the current subarray or start a new one
    maxCurrent = Math.max(num, maxCurrent + num); // Update maxCurrent

    // Update the overall maximum sum found so far
    if (maxCurrent > maxGlobal) { // Check if maxCurrent is greater than maxGlobal
      maxGlobal = maxCurrent; // If so, update maxGlobal
    }
  }

  return maxGlobal; // Return the largest sum found
};

