class BankAccount {
  constructor(initialBalance) {
    this.balance = initialBalance; // Initialize the account balance
  }

  deposit(amount) {
    this.balance += amount; // Add the deposit amount to the balance
    return this.balance; // Return the updated balance
  }

  withdraw(amount) {
    // Check if there are sufficient funds for the withdrawal
    if (this.balance >= amount) {
      this.balance -= amount; // Subtract the withdrawal amount
      return this.balance; // Return the new balance after withdrawal
    } else {
      // If insufficient funds, return the current balance unchanged
      console.log("Insufficient funds."); // Log a message for insufficient funds
      return this.balance;
    }
  }
}

