const countInversions = (nums) => {
  let inversions = 0; // Initialize a counter for inversions.

  // Iterate through the array with the first pointer 'i'.
  for (let i = 0; i < nums.length - 1; i++) {
    // Iterate with the second pointer 'j', starting from 'i + 1'.
    for (let j = i + 1; j < nums.length; j++) {
      // Check if the current pair (nums[i], nums[j]) forms an inversion.
      if (nums[i] > nums[j]) {
        inversions++; // Increment the inversion count if nums[i] is greater than nums[j].
      }
    }
  }
  // Return the total number of inversions found.
  return inversions; // This is the final result.
};

