function parseLogEntry(logLine) {
  // Find the index of the closing square bracket
  const closingBracketIndex = logLine.indexOf(']');

  // Check if a closing bracket was found and if there's content after it
  if (closingBracketIndex === -1 || closingBracketIndex + 1 >= logLine.length) {
    // Return a default object if the format is invalid
    return { timestamp: null, message: logLine };
  }

  // Extract the timestamp part, excluding the brackets
  const timestamp = logLine.substring(1, closingBracketIndex);

  // The message starts after the closing bracket and the subsequent space
  // Ensure there's a space after the bracket to avoid off-by-one errors
  let message = logLine.substring(closingBracketIndex + 1);

  // Trim leading whitespace from the message, which should be the space after the bracket
  message = message.trimStart(); 

  // Return the parsed object
  return {
    timestamp: timestamp, // Assign the extracted timestamp
    message: message     // Assign the extracted message
  };
}

