function daysUntil(futureDateString) {
  const MS_PER_DAY = 1000 * 60 * 60 * 24; // Define milliseconds in a day

  const today = new Date(); // Get today's date
  // Set today's time to midnight to ensure full day comparison
  today.setHours(0, 0, 0, 0); 

  const futureDate = new Date(futureDateString); // Create a Date object from the input string
  // Set the future date's time to midnight for consistency
  futureDate.setHours(0, 0, 0, 0); 

  // Calculate the difference in milliseconds between the two dates
  const timeDiff = futureDate.getTime() - today.getTime(); 

  // Convert the time difference to days
  const dayDiff = Math.round(timeDiff / MS_PER_DAY); // Round to the nearest whole day

  return dayDiff; // Return the number of full days remaining
}

