const isValidISBN10 = (isbn) => {
  // Remove hyphens from the ISBN string
  const cleanedIsbn = isbn.replace(/-/g, '');

  // Check if the cleaned ISBN has the correct length (10 characters)
  if (cleanedIsbn.length !== 10) {
    return false;
  }

  let sum = 0; // Initialize sum for checksum calculation
  // Iterate through each character of the cleaned ISBN
  for (let i = 0; i < 10; i++) {
    let digit = cleanedIsbn[i]; // Get the current character

    // Handle the 'X' character for the last digit
    if (digit === 'X' && i === 9) {
      sum += 10 * (10 - i); // 'X' counts as 10
    } else if (!isNaN(parseInt(digit))) { // Check if it's a valid digit
      sum += parseInt(digit) * (10 - i); // Multiply digit by its position
    } else {
      return false; // Invalid character found
    }
  }

  // The ISBN is valid if the sum is divisible by 11
  return sum % 11 === 0;
};

