const getQuadrant = (x, y) => {
  // Check if the point is on an axis or the origin.
  if (x === 0 || y === 0) {
    return 0; // Return 0 for points on an axis or origin.
  }

  // Determine the quadrant based on the signs of x and y.
  if (x > 0 && y > 0) {
    return 1; // First quadrant: x > 0, y > 0.
  } else if (x < 0 && y > 0) {
    // Check for the second quadrant.
    return 2; // Second quadrant: x < 0, y > 0.
  } else if (x < 0 && y < 0) {
    return 3; // Third quadrant: x < 0, y < 0.
  } else {
    // The only remaining case is the fourth quadrant.
    return 4; // Fourth quadrant: x > 0, y < 0.
  }
};

