function simulateCoinTosses(numTosses) {
  let heads = 0; // Initialize heads count
  let tails = 0; // Initialize tails count

  // Loop through the specified number of tosses
  for (let i = 0; i < numTosses; i++) {
    // Generate a random number between 0 (inclusive) and 1 (exclusive)
    const toss = Math.random(); 

    // If the random number is less than 0.5, it's a head
    if (toss < 0.5) {
      heads++; // Increment heads count
    } else {
      tails++; // Otherwise, it's a tail, so increment tails count
    }
  }

  // Return an object containing the final counts
  return { heads: heads, tails: tails }; // Return the result object
}

