const calculateDiscountedPrice = (originalPrice, discountPercentage) => {
  /* Validate input for originalPrice to be a non-negative number */
  if (typeof originalPrice !== 'number' || originalPrice < 0) {
    throw new Error('Original price must be a non-negative number.');
  }

  /* Validate input for discountPercentage to be a number between 0 and 100 */
  if (typeof discountPercentage !== 'number' || discountPercentage < 0 || discountPercentage > 100) {
    throw new Error('Discount percentage must be a number between 0 and 100.');
  }

  /* Calculate the discount amount */
  const discountAmount = originalPrice * (discountPercentage / 100);

  /* Calculate the final price by subtracting the discount amount */
  const finalPrice = originalPrice - discountAmount;

  /* Return the calculated final price */
  return finalPrice; /* This is the result of the calculation */
};

