const isPalindromeNumber = (num) => {
  // Convert the number to a string to easily reverse it.
  const numStr = String(num); 
  // Initialize an empty string to store the reversed version.
  let reversedStr = ""; 

  // Loop through the string from the end to the beginning.
  for (let i = numStr.length - 1; i >= 0; i--) { 
    // Append each character to build the reversed string.
    reversedStr += numStr[i]; 
  }

  // Compare the original string with the reversed string.
  // If they are identical, the number is a palindrome.
  return numStr === reversedStr; // Return true if they match, false otherwise.
};

