function groupByParity(numbers) {
  const result = { // Initialize an object to store the grouped numbers
    even: [],
    odd: []
  };

  for (let i = 0; i < numbers.length; i++) { // Loop through each number in the input array
    const num = numbers[i]; // Get the current number

    if (num % 2 === 0) { // Check if the number is even
      result.even.push(num); // Add even numbers to the 'even' array
    } else {
      result.odd.push(num); // Add odd numbers to the 'odd' array
    }
  }

  return result; // Return the object containing grouped even and odd numbers
}

