  // Get the month (0-indexed) from the Date object
  const month = date.getMonth(); 

  // Determine the season based on the month
  if (month >= 2 && month <= 4) { // March (2) to May (4)
    return 'Spring';
  } else if (month >= 5 && month <= 7) { // June (5) to August (7)
    return 'Summer';
  } else if (month >= 8 && month <= 10) { // September (8) to November (10)
    return 'Autumn';
  } else { // December (11), January (0), February (1)
    // This covers months 11, 0, and 1 for Winter
    return 'Winter'; 
  }
}

