const simulateQueue = (initialQueue, operations) => {
  let currentQueue = [...initialQueue]; // Create a shallow copy of the initial queue

  operations.forEach(operation => { // Iterate over each operation in the array
    if (operation.type === 'enqueue') {
      currentQueue.push(operation.value); // Add the value to the end of the queue
    } else if (operation.type === 'dequeue') {
      if (currentQueue.length > 0) { // Check if the queue is not empty before dequeuing
        currentQueue.shift(); // Remove the element from the beginning of the queue
      } // If the queue is empty, dequeue does nothing
    }
  });

  return currentQueue; // Return the final state of the queue
};

