const calculateRectangleDiagonal = (width, height) => {
  // Ensure width and height are positive numbers
  if (width <= 0 || height <= 0) {
    throw new Error("Width and height must be positive numbers.");
  }

  // Calculate the square of the width
  const widthSquared = width * width;
  // Calculate the square of the height
  const heightSquared = height * height;

  // Sum the squares of the width and height
  const sumOfSquares = widthSquared + heightSquared;

  // Calculate the square root of the sum
  const diagonal = Math.sqrt(sumOfSquares);

  // Return the calculated diagonal length
  return diagonal; // This is the final result
};

