const hasConflict = (existingEvent, newEvent) => {
  // Helper function to convert time strings to minutes for easier comparison
  const timeToMinutes = (timeString) => {
    const [hours, minutes] = timeString.split(':').map(Number); // Split string and convert to numbers
    return hours * 60 + minutes; // Calculate total minutes from midnight
  };

  // Convert existing event times to minutes
  const existingStart = timeToMinutes(existingEvent.start);
  const existingEnd = timeToMinutes(existingEvent.end); // End time of the existing event

  // Convert new event times to minutes
  const newStart = timeToMinutes(newEvent.start);
  const newEnd = timeToMinutes(newEvent.end); // Start time of the new event

  // Check for overlap conditions
  // An overlap occurs if the new event starts before the existing event ends AND
  // the new event ends after the existing event starts.
  // This covers cases where newEvent completely encloses existingEvent,
  // existingEvent completely encloses newEvent, or they partially overlap.
  const overlapCondition1 = newStart < existingEnd; // New event starts before existing event ends
  const overlapCondition2 = newEnd > existingStart; // New event ends after existing event starts

  // If both conditions are true, there is a conflict.
  return overlapCondition1 && overlapCondition2; // Return true if there's a conflict, false otherwise
};

