const calculateWeightedAverage = (data) => {
  let totalWeightedSum = 0; // Initialize a variable to store the sum of (value * weight)
  let totalWeight = 0;     // Initialize a variable to store the sum of all weights

  // Iterate over each item in the input data array
  for (const item of data) {
    totalWeightedSum += item.value * item.weight; // Add the product of value and weight to the running sum
    totalWeight += item.weight;                 // Add the current item's weight to the total weight
  }

  // Handle the case where totalWeight is zero to avoid division by zero
  if (totalWeight === 0) {
    return 0; // If there's no weight, the average is conventionally 0
  }

  // Calculate the weighted average by dividing the total weighted sum by the total weight
  return totalWeightedSum / totalWeight; // Return the final calculated weighted average
};

