function parseQueryString(queryString) {
  const result = {}; // Initialize an empty object to store the parsed key-value pairs.

  // Remove the leading '?' if it exists.
  const cleanString = queryString.startsWith('?') ? queryString.substring(1) : queryString;

  // Split the string into individual key-value pair strings.
  const pairs = cleanString.split('&'); 

  // Iterate over each key-value pair.
  for (const pair of pairs) {
    if (pair.length === 0) continue; // Skip empty pairs that might result from trailing '&'.

    const parts = pair.split('='); // Split each pair into key and value.
    const key = parts[0]; // The first part is the key.
    // The value might be empty, so handle undefined or missing parts correctly.
    const value = parts.length > 1 ? parts.slice(1).join('=') : ''; 

    result[key] = value; // Assign the extracted key and value to the result object.
  }

  return result; // Return the final parsed object.
}

