const formatDateToMMDDYYYY = (date) => {
  // Get the month from the Date object.
  const month = date.getMonth() + 1; // getMonth() is 0-indexed, so add 1
  // Get the day of the month.
  const day = date.getDate();
  // Get the full year.
  const year = date.getFullYear();

  // Pad month with a leading zero if it's a single digit.
  const paddedMonth = month < 10 ? '0' + month : month;
  // Pad day with a leading zero if it's a single digit.
  const paddedDay = day < 10 ? '0' + day : day;

  // Assemble the formatted date string using template literals.
  return `${paddedMonth}/${paddedDay}/${year}`; // Return the final string.
};

