const countWords = (sentence) => { // Declares a constant function named countWords
  if (!sentence) { // Checks if the input sentence is empty or null
    return 0; // If so, returns 0 as there are no words
  }

  // Splits the sentence by one or more spaces using a regular expression
  const words = sentence.split(/\s+/); // The '+' ensures multiple spaces are treated as one delimiter

  // Filters out any empty strings that might result from multiple spaces at the beginning/end
  const filteredWords = words.filter(word => word !== ''); // Removes empty strings from the array

  // Returns the number of valid words found
  return filteredWords.length; // Returns the count of the filtered words
};

