const areAnagrams = (str1, str2) => {
  // Helper function to clean and sort a string
  const cleanAndSort = (str) => {
    // Convert to lowercase to ignore case
    return str
      .toLowerCase()
      // Remove non-alphabetic characters
      .replace(/[^a-z]/g, '')
      .split('') // Split into an array of characters
      .sort() // Sort the characters alphabetically
      .join(''); // Join them back into a string
  };

  // Clean and sort both input strings
  const cleanedStr1 = cleanAndSort(str1);
  const cleanedStr2 = cleanAndSort(str2);

  // Compare the cleaned and sorted strings
  return cleanedStr1 === cleanedStr2; // If they are identical, they are anagrams
};

