  // Convert the input state to lowercase to handle variations in casing.
  const lowerCaseState = currentState.toLowerCase();

  // Use a switch statement to determine the next state based on the current state.
  switch (lowerCaseState) {
    case 'red':
      // If the current state is red, the next state is green.
      return 'green';
    case 'green':
      // If the current state is green, the next state is yellow.
