function mergeSortedArrays(arr1, arr2) {
  const merged = []; // Initialize an empty array to store the merged result.
  let i = 0; // Pointer for the first array.
  let j = 0; // Pointer for the second array.

  // Loop while both pointers are within their respective array bounds.
  while (i < arr1.length && j < arr2.length) {
    if (arr1[i] < arr2[j]) { // Compare elements from both arrays.
      merged.push(arr1[i]); // Add the smaller element to the merged array.
      i++; // Move the pointer for the first array.
    } else {
      merged.push(arr2[j]); // Add the smaller element (from arr2) to merged.
      j++; // Move the pointer for the second array.
    }
  }

  // Add any remaining elements from arr1 (if arr2 was exhausted first).
  while (i < arr1.length) {
    merged.push(arr1[i]);
    i++;
  }

  // Add any remaining elements from arr2 (if arr1 was exhausted first).
  while (j < arr2.length) {
    merged.push(arr2[j]);
    j++;
  }

  return merged; // Return the fully merged and sorted array.
}

