  let startCharCode = letters[0].charCodeAt(0);

  // Iterate through the array of letters.
  for (let i = 0; i < letters.length; i++) {
    // Get the character code of the current letter.
    const currentCharCode = letters[i].charCodeAt(0);

    // Check if the current letter's code is not what's expected.
    if (currentCharCode !== startCharCode + i) {
      // If a discrepancy is found, the missing letter is the expected one.
      return String.fromCharCode(startCharCode + i);
