const getDaysInMonth = (year, month) => {
  // Check if the year is a leap year.
  const isLeapYear = (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);

  // Array to store the number of days in each month.
  const daysInMonths = [
    0, // Dummy value for 0-indexed month array, as month is 1-indexed.
    31, // January
    28, // February (default)
    31, // March
    30, // April
    31, // May
    30, // June
    31, // July
    31, // August
    30, // September
    31, // October
    30, // November
    31  // December
  ];

  // Adjust February's days if it's a leap year.
  if (isLeapYear) {
    daysInMonths[2] = 29; // February has 29 days in a leap year.
  }

  // Return the number of days for the specified month.
  return daysInMonths[month];
};

