function decodeCaesarCipher(encryptedText, shift) {
  let decodedText = ''; // Initialize an empty string to store the decoded message.

  for (let i = 0; i < encryptedText.length; i++) {
    const char = encryptedText[i]; // Get the current character from the encrypted text.
    let charCode = char.charCodeAt(0); // Get the ASCII value of the character.

    // Calculate the new ASCII code after shifting.
    // 'a' is ASCII 97. We subtract 'a' to get a 0-25 range.
    let decodedCharCode = ((charCode - 97 - shift + 26) % 26) + 97; // Apply the shift and handle wrap-around.

    // Convert the new ASCII code back to a character.
    decodedText += String.fromCharCode(decodedCharCode); // Append the decoded character to the result string.
  }

  return decodedText; // Return the completely decoded message.
}

// Example usage and testing:
// console.log(decodeCaesarCipher('khoor', 3)); // Should output 'hello'
// console.log(decodeCaesarCipher('abc', 1));   // Should output 'zab'

