  let totalValue = 0; // Initialize total value accumulator

  // Iterate over each item in the inventory array
  for (let i = 0; i < items.length; i++) {
    const item = items[i]; // Get the current item object
    // Calculate the value of the current item (price * quantity)
    const itemValue = item.price * item.quantity;
    totalValue += itemValue; // Add the item's value to the total
  }

  // Return the accumulated total monetary value
  return totalValue;
};

