const calculateTip = (billTotal, tipPercentage) => {
  // Ensure billTotal is a positive number.
  if (typeof billTotal !== 'number' || billTotal < 0) {
    throw new Error('Bill total must be a non-negative number.');
  }

  // Ensure tipPercentage is a number between 0 and 100.
  if (typeof tipPercentage !== 'number' || tipPercentage < 0 || tipPercentage > 100) {
    throw new Error('Tip percentage must be a number between 0 and 100.');
  }

  // Convert the percentage to a decimal.
  const tipDecimal = tipPercentage / 100; 

  // Calculate the raw tip amount.
  const tipAmount = billTotal * tipDecimal; 

  // Round the tip amount to two decimal places for currency.
  return Math.round(tipAmount * 100) / 100; // Return the calculated tip.
};

