function formatSecondsToHMS(totalSeconds) {
  // Calculate hours by dividing total seconds by seconds in an hour
  const hours = Math.floor(totalSeconds / 3600);
  // Calculate remaining seconds after extracting hours
  let remainingSeconds = totalSeconds % 3600;

  // Calculate minutes from the remaining seconds
  const minutes = Math.floor(remainingSeconds / 60);
  // Calculate the final seconds after extracting minutes
  const seconds = remainingSeconds % 60;

  // Helper function to zero-pad a number if it's less than 10
  const pad = (num) => {
    // Convert number to string and pad with '0' if length is 1
    return num < 10 ? '0' + num : '' + num;
  };

  // Pad hours, minutes, and seconds to ensure two digits
  const paddedHours = pad(hours);
  const paddedMinutes = pad(minutes);
  const paddedSeconds = pad(seconds);

  // Combine the padded components into the final HH:MM:SS string
  return `${paddedHours}:${paddedMinutes}:${paddedSeconds}`; // Return the formatted string
}

