const longestCommonSuffix = (strings) => {
  if (!strings || strings.length === 0) {
    return ""; // Handle empty or null input array.
  }

  if (strings.length === 1) {
    return strings[0]; // If only one string, it's its own longest suffix.
  }

  let suffix = ""; // Initialize the common suffix.
  let minLength = Math.min(...strings.map(s => s.length)); // Find the length of the shortest string.

  // Iterate from the end of the strings.
  for (let i = 1; i <= minLength; i++) {
    const char = strings[0][strings[0].length - i]; // Get the character from the end of the first string.

    // Check if this character is common to all strings at the current position.
    for (let j = 1; j < strings.length; j++) {
      if (strings[j][strings[j].length - i] !== char) {
        return suffix; // If not common, return the accumulated suffix.
      }
    }
    suffix = char + suffix; // Prepend the common character to the suffix.
  }

  return suffix; // Return the final longest common suffix.
};

