function metersToFeet(meters) {
  // Define the conversion factor from meters to feet
  const CONVERSION_FACTOR = 3.28084; 

  // Check if the input is a valid number
  if (typeof meters !== 'number' || isNaN(meters)) {
    // If not a number, return an error message or throw an error
    return "Invalid input: Please provide a number."; 
  }

  // Handle negative input by returning 0 feet (or could throw an error)
  if (meters < 0) { 
    return 0; // A negative length doesn't make physical sense for feet
  }

  // Perform the conversion
  const feet = meters * CONVERSION_FACTOR; 

  // Return the calculated value in feet
  return feet; // The final result of the conversion
}

