  const uniqueElements = new Set(arr);

  /* Compare the size of the Set to the length of the original array.
   * If they are equal, it means all elements were unique. */
  if (uniqueElements.size === arr.length) {
    return true; /* All elements are unique. */
  } else {
    return false; /* Duplicate elements were found. */
  }
