const getRandomInt = (min, max) => {
  // Ensure min and max are integers
  min = Math.ceil(min); 
  max = Math.floor(max);

  // Handle the case where min is greater than max by swapping them
  if (min > max) {
    [min, max] = [max, min]; // Destructuring assignment for swapping
  }

  // Calculate the range of possible values
  const range = max - min + 1; 

  // Generate a random number between 0 (inclusive) and 1 (exclusive)
  const randomNumber = Math.random(); 

  // Scale the random number to fit within the desired range
  const scaledNumber = randomNumber * range; 

  // Floor the scaled number to get an integer offset
  const offset = Math.floor(scaledNumber);

  // Add the minimum value to the offset to get the final result
  return min + offset; 
};

