const countTrailingZeros = (n) => {
  if (n < 0) {
    return 0; // Trailing zeros are not defined for negative numbers.
  }

  let count = 0; // Initialize a counter for trailing zeros.
  let powerOf5 = 5; // Start with the first power of 5.

  // Loop while the current power of 5 is less than or equal to n.
  while (powerOf5 <= n) {
    // Add the number of multiples of the current power of 5.
    count += Math.floor(n / powerOf5);
    // Move to the next power of 5.
    powerOf5 *= 5;
  }

  return count; // Return the total count of trailing zeros.
};

