const isValidHexColor = (hex) => {
  if (typeof hex !== 'string') { // Ensure input is a string
    return false;
  }

  if (!hex.startsWith('#')) { // Hex codes must start with '#'
    return false;
  }

  const cleanHex = hex.substring(1); // Remove the '#' prefix

  if (cleanHex.length !== 3 && cleanHex.length !== 6) { // Check for correct length
    return false;
  }

  const hexRegex = /^[0-9a-fA-F]+$/; // Regular expression for hex characters
  return hexRegex.test(cleanHex); // Test if all characters are valid hex digits
};

