const restockItem = (inventory, itemName, quantityToAdd) => {
  // Check if the item already exists in the inventory
  if (inventory.hasOwnProperty(itemName)) {
    // If it exists, update its quantity by adding quantityToAdd
    inventory[itemName] += quantityToAdd;
  } else {
    // If the item does not exist, add it to the inventory
    inventory[itemName] = quantityToAdd; // Set the new item's quantity
  }
  // The function modifies the inventory object directly
  return inventory; // Return the updated inventory object
};

