const getOverlappingEvents = (newEvent, existingEvents) => {
  // Helper to convert HH:MM string to minutes from midnight
  const timeToMinutes = (time) => {
    const [hours, minutes] = time.split(':').map(Number);
    return hours * 60 + minutes;
  };

  // Convert new event times to minutes for easier comparison
  const newEventStart = timeToMinutes(newEvent.start);
  const newEventEnd = timeToMinutes(newEvent.end);

  // Filter the existing events
  return existingEvents.filter(existingEvent => {
    // Convert existing event times to minutes
    const existingEventStart = timeToMinutes(existingEvent.start);
    const existingEventEnd = timeToMinutes(existingEvent.end);

    // Check for overlap condition
    // An overlap occurs if the new event starts before the existing event ends AND
    // the new event ends after the existing event starts.
    const overlaps = newEventStart < existingEventEnd && newEventEnd > existingEventStart;

    // Return true if an overlap is found, false otherwise
    return overlaps;
  });
};

