const calculateRange = (numbers) => {
  // Handle empty array case
  if (numbers.length === 0) {
    return 0; // The range of an empty set is conventionally 0
  }

  // Initialize min and max with the first element
  let min = numbers[0];
  let max = numbers[0];

  // Iterate through the array starting from the second element
  for (let i = 1; i < numbers.length; i++) {
    const currentNumber = numbers[i]; // Get the current number

    // Update minimum if current number is smaller
    if (currentNumber < min) {
      min = currentNumber;
    }

    // Update maximum if current number is larger
    if (currentNumber > max) {
      max = currentNumber;
    }
  }

  // Calculate and return the difference
  return max - min; // The range is max - min
};

