function playRPSRound(player1Choice, player2Choice) {
  // Define winning conditions for Player 1
  const winningConditions = {
    rock: 'scissors',
    paper: 'rock',
    scissors: 'paper'
  };

  // Check for a tie first
  if (player1Choice === player2Choice) {
    return "It's a Tie!"; // Return tie message
  }

  // Determine if Player 1 wins
  if (winningConditions[player1Choice] === player2Choice) {
    return "Player 1 Wins"; // Player 1's choice beats Player 2's
  }

  // If no tie and Player 1 didn't win, Player 2 must win
  return "Player 2 Wins"; // This covers all other scenarios
}

