function getFilenameFromPath(filePath) {
  // Find the index of the last occurrence of the path separator
  const lastSlashIndex = filePath.lastIndexOf('/'); 

  // If no slash is found, the entire string is the filename
  if (lastSlashIndex === -1) {
    return filePath; // Return the original path
  }

  // Extract the substring starting after the last slash
  const filename = filePath.substring(lastSlashIndex + 1); // Get the filename part

  return filename; // Return the extracted filename
}

