const calculateGCD = (a, b) => {
  // Ensure inputs are non-negative
  if (a < 0 || b < 0) {
    throw new Error("Inputs must be non-negative integers.");
  }

  // Loop until b becomes 0
  while (b !== 0) {
    // Store the current value of b in a temporary variable
    const temp = b;
    // Update b to be the remainder of a divided by b
    b = a % b;
    // Update a to be the previous value of b (stored in temp)
    a = temp; // This is the core of the Euclidean algorithm
  }
  // When b is 0, a holds the GCD
  return a; // The result is the final value of 'a'
};

// Example usage and testing
