const containsSubarray = (mainArray, subArray) => {
  // If the subArray is empty, it's always considered a subsequence.
  if (subArray.length === 0) {
    return true;
  }
  // If the mainArray is shorter than the subArray, it cannot contain it.
  if (mainArray.length < subArray.length) {
    return false;
  }

  // Iterate through the mainArray to find potential starting points for the subArray.
  for (let i = 0; i <= mainArray.length - subArray.length; i++) {
    let match = true; // Assume a match until proven otherwise.
    // Compare elements of the subArray with the corresponding slice of the mainArray.
    for (let j = 0; j < subArray.length; j++) {
