const isValidPassword = (password) => {
  // Check if the password is at least 8 characters long
  if (password.length < 8) {
    return false;
  }

  let hasUppercase = false; // Flag to track uppercase letter presence
  let hasNumber = false;   // Flag to track number presence

  // Iterate through each character of the password
  for (let i = 0; i < password.length; i++) {
    const char = password[i]; // Get the current character

    // Check if the character is an uppercase letter
    if (char >= 'A' && char <= 'Z') {
      hasUppercase = true;
    }
    // Check if the character is a digit
    if (char >= '0' && char <= '9') {
      hasNumber = true;
    }
  }

  // Return true only if both conditions are met
  return hasUppercase && hasNumber;
};

