const getElapsedTimeInMinutes = (startTime, endTime) => {
  // Split the start time string into hours and minutes
  const [startHourStr, startMinuteStr] = startTime.split(':');
  // Parse start hour to integer
  const startHour = parseInt(startHourStr, 10);
  // Parse start minute to integer
  const startMinute = parseInt(startMinuteStr, 10);

  // Split the end time string into hours and minutes
  const [endHourStr, endMinuteStr] = endTime.split(':');
  // Parse end hour to integer
  const endHour = parseInt(endHourStr, 10);
  // Parse end minute to integer
  const endMinute = parseInt(endMinuteStr, 10);

  // Calculate total minutes from midnight for the start time
  const totalStartMinutes = startHour * 60 + startMinute;
  // Calculate total minutes from midnight for the end time
  const totalEndMinutes = endHour * 60 + endMinute;

  // Return the difference in total minutes
  return totalEndMinutes - totalStartMinutes;
};

