function calculateTrapezoidArea(b1, b2, h) {
  // Check if all inputs are numbers
  if (typeof b1 !== 'number' || typeof b2 !== 'number' || typeof h !== 'number') {
    // Throw an error if any input is not a number
    throw new Error("All inputs must be numbers.");
  }

  // Ensure bases and height are non-negative
  if (b1 < 0 || b2 < 0 || h < 0) {
    // Throw an error for invalid dimensions
    throw new Error("Bases and height cannot be negative.");
  }

  // Sum the lengths of the two parallel bases
  const sumOfBases = b1 + b2;

  // Multiply the sum of bases by the height
  const productOfSumAndHeight = sumOfBases * h;

  // Calculate the area using the trapezoid formula
  const area = 0.5 * productOfSumAndHeight; // The core calculation

  // Return the calculated area
  return area; // The final result
}

