const extractDomain = (url) => {
  let domain = url; // Initialize domain with the full URL

  // Remove protocol part (http://, https://)
  if (domain.startsWith('http://')) {
    domain = domain.substring(7);
  } else if (domain.startsWith('https://')) {
    domain = domain.substring(8);
  }

  // Remove 'www.' if present at the beginning
  if (domain.startsWith('www.')) {
    domain = domain.substring(4);
  }

  // Find the first slash, which indicates the end of the domain
  const slashIndex = domain.indexOf('/');
  if (slashIndex !== -1) {
    domain = domain.substring(0, slashIndex); // Extract the part before the path
  }

  // Handle cases where there might be query parameters or hash after the domain
  const questionMarkIndex = domain.indexOf('?');
  if (questionMarkIndex !== -1) {
    domain = domain.substring(0, questionMarkIndex);
  }

  const hashIndex = domain.indexOf('#'); // Check for hash fragments
  if (hashIndex !== -1) {
    domain = domain.substring(0, hashIndex);
  }

  return domain; // Return the cleaned domain string
};

