function calculateFactorial(n) {
  // Check if the input is a non-negative integer.
  if (n < 0 || !Number.isInteger(n)) {
    // For invalid inputs, throw an error.
    throw new Error("Input must be a non-negative integer.");
  }

  // Base case: factorial of 0 is 1.
  if (n === 0) {
    return 1;
  }

  let result = 1; // Initialize the result to 1.

  // Loop from n down to 1 to multiply each number.
  for (let i = n; i > 0; i--) {
    result *= i; // Multiply the current number by the running result.
  }

  // The loop has finished, so 'result' now holds the factorial.
  return result; // Return the final calculated factorial.
}

// Example usage:
// calculateFactorial(5) would return 120.
// calculateFactorial(0) would return 1.
// calculateFactorial(3) would return 6.

