function startsWith(mainStr, prefix) {
  // Check if the main string is shorter than the prefix.
  if (mainStr.length < prefix.length) {
    return false; // Cannot start with a longer string.
  }

  // Iterate through the characters of the prefix.
  for (let i = 0; i < prefix.length; i++) {
    // Compare characters at the current index.
    if (mainStr[i] !== prefix[i]) {
      // If a mismatch is found, the string does not start with the prefix.
      return false;
    }
  }

  // If the loop completes, all characters matched.
  return true; // The main string indeed starts with the prefix.
}

