function power(base, exponent) {
  // Handle the edge case where the exponent is 0
  if (exponent === 0) {
    return 1;
  }

  let result = 1; // Initialize the result to 1

  // Determine the absolute value of the exponent for the loop
  const absExponent = Math.abs(exponent);

  // Loop to multiply the base by itself 'absExponent' times
  for (let i = 0; i < absExponent; i++) {
    result *= base; // Multiply the current result by the base
  }

  // Handle negative exponents
  if (exponent < 0) {
    return 1 / result; // For negative exponents, the result is 1 divided by the positive power
  }

  return result; // Return the final calculated result
}

