function toKebabCase(str) {
  if (!str) { // Handle empty or null input strings
    return '';
  }

  // Convert the first character to lowercase if it's uppercase (PascalCase)
  let result = str.replace(/^[A-Z]/, (match) => match.toLowerCase());

  // Replace uppercase letters (preceded by a lowercase letter) with - and lowercase
  result = result.replace(/([a-z0-9]|(?=[A-Z]))([A-Z])/g, '$1-$2'); // This handles camelCase conversions

  // Ensure multiple hyphens are not introduced when consecutive uppercase letters are present
  result = result.replace(/([A-Z])([A-Z][a-z])/g, '$1-$2'); // This specifically addresses "HTTPResponse" to "http-response"

  // Convert the entire string to lowercase to handle any remaining uppercase letters
  result = result.toLowerCase(); // Final conversion to ensure all characters are lowercase

  // Remove any leading or trailing hyphens that might have been introduced
  return result.replace(/^-+|-+$/g, ''); // Clean up any extraneous hyphens
}

