const isPalindrome = (str) => {
  // Get the length of the input string
  const len = str.length;
  // Iterate from the beginning to the middle of the string
  for (let i = 0; i < len / 2; i++) {
    // Compare the character at the current index with its corresponding character from the end
    if (str[i] !== str[len - 1 - i]) { // If characters do not match
      return false; // It's not a palindrome
    }
  }
  // If the loop completes, it means all corresponding characters matched
  return true; // The string is a palindrome
};

