const truncateString = (str, maxLength) => {
  // Check if the string's length is already within the limit
  if (str.length <= maxLength) {
    return str; // Return the original string if no truncation is needed
  }

  // Calculate the length for the truncated part, accounting for '...'
  const truncationLength = maxLength - 3;
  // Ensure we don't end up with a negative length if maxLength is too small
  if (truncationLength <= 0) {
    return '...'; // If maxLength is too small, just return '...'
  }

  // Slice the string to the calculated truncation length
  const truncatedPart = str.slice(0, truncationLength);
  // Append '...' to the truncated part
  const result = truncatedPart + '...';
  // Return the final truncated string
  return result;
};

