const countWords = (str) => {
  // Trim leading/trailing whitespace from the input string
  const trimmedStr = str.trim();

  // If the string is empty after trimming, there are no words
  if (trimmedStr === '') {
    return 0;
  }

  // Split the string by one or more spaces using a regular expression
  const words = trimmedStr.split(/\s+/); // Use regex to handle multiple spaces between words

  // Filter out any empty strings that might result from extra spaces
  const filteredWords = words.filter(word => word !== ''); // Ensure no empty strings are counted as words

  // Return the count of the filtered words
  return filteredWords.length; // This is the final word count.
};

