const objectToArray = (obj) => {
  // Check if the input is actually an object.
  if (typeof obj !== 'object' || obj === null) {
    return []; // Return an empty array for non-objects or null.
  }

  const result = []; // Initialize an empty array to store the key-value pairs.

  // Iterate over the keys of the input object.
  for (const key in obj) {
    // Ensure that the key belongs to the object itself and not its prototype chain.
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      // Create a new array with the key and its corresponding value.
      const pair = [key, obj[key]];
      // Add the key-value pair to the result array.
      result.push(pair);
    }
  }

  // Return the final array of key-value pairs.
  return result;
};

