function endsWith(mainStr, suffix) {
  // Get the length of the main string.
  const mainLen = mainStr.length;
  // Get the length of the suffix string.
  const suffixLen = suffix.length;

  // If the suffix is longer than the main string, it cannot be a suffix.
  if (suffixLen > mainLen) {
    return false;
  }

  // Calculate the starting index in the main string for comparison.
  const startIndex = mainLen - suffixLen;

  // Iterate from the calculated starting index to the end of the main string.
  for (let i = 0; i < suffixLen; i++) {
    // Compare characters from mainStr and suffix.
    if (mainStr[startIndex + i] !== suffix[i]) {
      // If any character doesn't match, it's not a suffix.
      return false;
    }
  }
  // If the loop completes, all characters matched, so it is a suffix.
  return true;
}

