const queue = []; // Initialize an empty array to represent the queue.

function enqueue(item) {
  queue.push(item); // Add the item to the end of the array.
}

function dequeue() {
  if (queue.length === 0) { // Check if the queue is empty.
    return null; // Return null if there are no items to dequeue.
  }
  return queue.shift(); // Remove and return the first element from the array.
}

